splash=f'''<div id="splash"><div class="in">{emb}<h1>بيئة التعلم الإلكتروني</h1><p>لتنمية المفاهيم التكنولوجية والدافعية للتعلم لدى تلاميذ المرحلة الابتدائية</p><small>جامعة الزقازيق – كلية التربية النوعية</small><button class="btn" id="enter">انقر للدخول</button></div></div>'''
people="".join(f"<div><b>{a}</b><br><small>{b}</small></div>" for a,b in ppl)
about=f'''<dialog id="about"><h2>عن الدراسة</h2><p><b>«التفاعل بين نمطي الخرائط الذهنية الإلكترونية والأسلوب المعرفي في بيئة تعلم إلكتروني على تنمية المفاهيم التكنولوجية والدافعية للتعلم لدى تلاميذ المرحلة الابتدائية ذوي صعوبات التعلم»</b></p><p><b>إعداد الباحثة:</b> أسماء محمد الحسيني أحمد – مدرس مساعد بقسم تكنولوجيا التعليم، كلية التربية النوعية – جامعة الزقازيق.</p><h2>لجنة الإشراف</h2><div class="people">{people}</div><button class="btn" onclick="this.closest('dialog').close()">إغلاق</button></dialog>'''
sup="".join(f'<div class="pcard"><h3>{a}</h3><small>{b}</small></div>' for a,b in ppl)
w("index.html","الرئيسية","index",splash+f'''<main class="wrap home"><div class="thesis">«التفاعل بين نمطي الخرائط الذهنية الإلكترونية والأسلوب المعرفي في بيئة تعلم إلكتروني على تنمية <b>المفاهيم التكنولوجية والدافعية للتعلم</b> لدى تلاميذ المرحلة الابتدائية ذوي صعوبات التعلم»</div>
<div class="lbl">إعداد</div><div class="pcard me"><h3>أسماء محمد الحسيني أحمد</h3><small>مدرس مساعد بقسم تكنولوجيا التعليم – كلية التربية النوعية – جامعة الزقازيق</small></div>
<div class="lbl">إشراف</div><div class="sup">{sup}</div>
<div style="margin-top:6px"><a class="btn gostart" href="login.html">🚀 ابدأ التعلم</a></div></main>''','''<script>(function(){var s=document.getElementById("splash");if(sessionStorage.getItem("seen")){s.remove();return}
function go(){sessionStorage.setItem("seen","1");s.classList.add("hide");setTimeout(function(){s.remove()},900)}document.getElementById("enter").onclick=go;document.getElementById("enter").focus()})()</script>''')
