w("guide.html","دليل التعلم","guide",'<main class="wrap"><h1 >دليل التعلم</h1><p>مرحبًا بك! هنا تجد كل ما تحتاجه لتستخدم البيئة بسهولة.</p><div class="grid g3">'+"".join(f'<div class="card"><div class="em">{a}</div><h3>{b}</h3><small>{c}</small></div>' for a,b,c in steps)+'</div></main>')
